∀ (s : Rocq.Corelib.Init.Hexadecimal.signed_int),
  NativeBridge.Incremental.NumericSigned.optionNatTo (Rocq.Corelib.Init.Nat.of_hex_int s) =
    have n := NativeBridge.Incremental.NumericWrite.hexadecimalSignedTo (Rocq.Corelib.Init.Hexadecimal.norm s);
    if n.fst = true then none else some (List.foldl (fun a d => 16 * a + ↑d) 0 n.snd)

∀ (s : Bool × List (Fin 10)),
  NativeBridge.Incremental.NumericWrite.decimalSignedOf s =
    if s.fst = true then Rocq.Corelib.Init.Decimal.signed_int.Neg (NativeBridge.decimalDigitsOf s.snd)
    else Rocq.Corelib.Init.Decimal.signed_int.Pos (NativeBridge.decimalDigitsOf s.snd)

∀ (s : Bool × List (Fin 16)),
  NativeBridge.Incremental.NumericWrite.hexadecimalSignedOf s =
    if s.fst = true then Rocq.Corelib.Init.Hexadecimal.signed_int.Neg (NativeBridge.hexadecimalDigitsOf s.snd)
    else Rocq.Corelib.Init.Hexadecimal.signed_int.Pos (NativeBridge.hexadecimalDigitsOf s.snd)

∀ (s : Rocq.Corelib.Init.Decimal.signed_int),
  NativeBridge.Incremental.NumericSigned.optionNatTo (Rocq.Corelib.Init.Nat.of_int s) =
    have n := NativeBridge.Incremental.NumericWrite.decimalSignedTo (Rocq.Corelib.Init.Decimal.norm s);
    if n.fst = true then none else some (List.foldl (fun a d => 10 * a + ↑d) 0 n.snd)
